package com.dshgo.shellpol;
import org.junit.Test;import static org.junit.Assert.*;
public class ShellRequestPolicyTest{@Test public void acceptsLongUtf8AndShellSyntax(){StringBuilder c=new StringBuilder("for x in *; do printf '%s\\n' \"$x\"; done # ");for(int i=0;i<100000;i++)c.append('\u4e2d');assertNull(ShellRequestPolicy.commandError(c.toString()));assertNull(ShellRequestPolicy.commandError("printf 'a\\nb' | cat && echo done"));}@Test public void rejectsEmptyAndNulCommands(){assertEquals("invalidCommand",ShellRequestPolicy.commandError(null));assertEquals("invalidCommand",ShellRequestPolicy.commandError(" \r\n\t"));assertEquals("invalidCommand",ShellRequestPolicy.commandError("echo a\0b"));}@Test public void timeoutHasNoConvenienceCeilingButAllowsCleanupArithmetic(){assertNull(ShellRequestPolicy.timeoutError(100L));assertNull(ShellRequestPolicy.timeoutError(60001L));assertNull(ShellRequestPolicy.timeoutError(8L*24*60*60*1000));assertNull(ShellRequestPolicy.timeoutError(Long.MAX_VALUE-2000L));assertEquals("invalidTimeout",ShellRequestPolicy.timeoutError(99L));assertEquals("invalidTimeout",ShellRequestPolicy.timeoutError(Long.MAX_VALUE));}@Test public void preservesIntegerSchema(){assertEquals(Long.valueOf(120000),ShellRequestPolicy.timeout(120000));assertEquals(Long.valueOf(120000),ShellRequestPolicy.timeout(120000L));assertNull(ShellRequestPolicy.timeout(120000.5));assertNull(ShellRequestPolicy.timeout(Double.NaN));assertNull(ShellRequestPolicy.timeout("120000"));assertNull(ShellRequestPolicy.timeout(null));}}
